import{_ as t,o as n,c as a,a5 as i}from"./chunks/framework.DvE3tBec.js";const f=JSON.parse('{"title":"First week of intensive collaboration: Dec 4-6, 2017","description":"","frontmatter":{"news":true,"title":"First week of intensive collaboration: Dec 4-6, 2017","date":"2017-12-18T00:00:00.000Z","author":"Edzer Pebesma","aside":false},"headers":[],"relativePath":"news/2017-12-18-VITO_meeting.md","filePath":"news/2017-12-18-VITO_meeting.md","lastUpdated":1791387718000}'),o={name:"news/2017-12-18-VITO_meeting.md"};function r(s,e,l,d,c,p){return n(),a("div",null,[...e[0]||(e[0]=[i('<p>On Dec 4-6, VITO&#39;s <a href="https://remotesensing.vito.be/" target="_blank" rel="noreferrer">remote sensing lab</a> hosted the first openEO <em>week of intensive collaboration</em>, in Mol, Belgium. Thirteen developers from 8 different partners gathered to discuss, and work on realising the <a href="https://appelmar.github.io/openeo-api-docs/poc/index.html" target="_blank" rel="noreferrer">first three use cases</a>, which are planned to be delivered in Month 6 (March 2018):</p><blockquote><p>First week of intense collaboration for #openEO @VITO_RS_, drafting a first API and doing use cases. @MundialisInfo @EODC_GmbH #ifgi @CopernicusEU @sinergise @EURAC #JRC <a href="https://t.co/9uCYd9A96S" target="_blank" rel="noreferrer">pic.twitter.com/9uCYd9A96S</a></p><p>— openEO (@open_EO) <a href="https://twitter.com/open_EO/status/938000627078230016" target="_blank" rel="noreferrer">December 5, 2017</a></p></blockquote><p>We worked on the following back-ends:</p><ul><li>Sentinel hub</li><li>EODC file-based</li><li>Rasdaman</li><li>GRASS</li><li>GeoTrellis</li></ul><p>and on the R and python clients, and started working on a <a href="/documentation/1.0/glossary.html">glossary</a>.</p><p>Among the many insights we gathered by sitting together and talk, we found that</p><ul><li>the &quot;core API&quot; as described in the proposal is not so much a software layer on itself, but rather an API in front of every compute back-end; this simplifies the whole architecture pretty much</li><li>OpenSearch should have the ability to describe <em>collections</em> of granules (or images, tiles) in addition to describing individual granules</li><li>band can be seen as array dimension as well as attributes of array records, but seeing it as a dimension may make life easier</li><li>use case 1 can be described as a sequence of filter operations (on image collection, bounding box, date range, and bands) followed by two aggregate operations (compute division over bands, compute mininum over time)</li></ul><p>Intermediate results can be found in a bunch of repositories, mostly proof-of-concept, on the openEO <a href="https://github.com/Open-EO/" target="_blank" rel="noreferrer">Github organisation</a>.</p>',8)])])}const m=t(o,[["render",r]]);export{f as __pageData,m as default};
